/* customer.c */
struct customer { CustomerId id; char *name; /* ... */ };

Customer *customer_create(const char *name) {
    Customer *c = malloc(sizeof *c);
    c->id = next_customer_id();          /* identity assigned once */
    c->name = strdup(name);
    return c;
}
bool customer_same(const Customer *a, const Customer *b) {
    return customer_id(a) == customer_id(b);   /* identity, never name */
}
